class Document(_IotTwinDocument, DocumentRef):
    """A document, loaded."""

    @classmethod
    def _from(cls, session: _Session, scope: _Key, data: _IotTwinDocument) -> Self:
        ref_key: _Key = {**scope}
        ref_key["document_name"] = _text(data.document_name)
        ref_key["region"] = _text(getattr(data, "region", None)) or scope.get("region")
        return _bind(cls, session, data, ref_key)


class DocumentCollection(_Collection[Document]):
    """Every document: iterate, `filter`, or call with an identifier."""

    def __call__(
        self, document_name: str, /, *, region: str | None = None
    ) -> DocumentRef:
        ref_key: _Key = {**self._scope, "document_name": _identifier(document_name)}
        ref_key["region"] = region or self._criteria.get("region")
        return DocumentRef._of(self._session, ref_key)


